from __future__ import annotations

def seo_guides() -> list[dict]:
    return [
        {"slug":"concrete-driveway-thickness-guide","title":"Concrete Driveway Thickness Planning Guide","category":"Concrete & Masonry","topic":"concrete","parent":"concrete-driveway-calculator","description":"Plan driveway concrete volume after choosing a project-appropriate slab thickness.","answer":"Driveway thickness is not a universal calculator setting. Light residential traffic, heavy vehicles, soil conditions, base preparation and reinforcement can change the design. Once the designed thickness is known, convert inches to feet and calculate length × width × thickness ÷ 27 for cubic yards.","steps":[("Define the use","Record cars, trucks, equipment and expected traffic."),("Check the base","Poor or wet subgrade can affect the design more than the surface area."),("Measure the slab","Split widening, apron and turning areas into rectangles."),("Calculate volume","Use the designed thickness, then review reinforcement, joints and ordering allowance.")],"formula":"cubic yards = length(ft) × width(ft) × thickness(ft) ÷ 27","example":"A 40 ft × 12 ft driveway at 5 in is 40 × 12 × 0.4167 ÷ 27 ≈ 7.41 yd³ before allowance.","mistakes":"Choosing thickness from a generic internet rule, forgetting the apron, and adding waste by inflating every dimension can all distort the estimate.","faqs":[("Does a thicker driveway always last longer?","Not by itself. Base, drainage, concrete quality, joints and curing also matter."),("Should the apron be included?","Measure the apron separately and add its volume."),("Is this structural advice?","No. Confirm design and local requirements with a qualified professional.") ]},
        {"slug":"concrete-footing-size-guide","title":"Concrete Footing Volume Planning Guide","category":"Concrete & Masonry","topic":"concrete","parent":"concrete-footing-calculator","description":"Calculate concrete volume for strip footings and pad footings while keeping structural design separate.","answer":"Calculate each footing type separately. A continuous footing uses length × width × depth, while an isolated pad uses pad length × pad width × pad depth. Add all sections, then convert cubic feet to cubic yards.","steps":[("List footing types","Separate continuous walls, isolated pads and steps."),("Use designed dimensions","Do not substitute excavation dimensions for concrete dimensions."),("Calculate each section","Multiply length, width and depth in feet."),("Add and convert","Total cubic feet ÷ 27 gives cubic yards before ordering rules.")],"formula":"footing volume(ft³) = length × width × depth; yd³ = total ft³ ÷ 27","example":"A 60 ft strip footing 1.5 ft wide and 0.75 ft deep is 67.5 ft³, or 2.50 yd³.","mistakes":"Confusing trench size with concrete size, ignoring steps, and estimating reinforcement from volume alone.","faqs":[("Are footing dimensions universal?","No. Soil, loads, frost depth and local rules control design."),("Can I combine pads and strip footings?","Calculate them separately and add the volumes."),("Does this design a foundation?","No. It is only a quantity estimate.") ]},
        {"slug":"small-bathroom-remodel-budget","title":"Small Bathroom Remodel Budget Guide","category":"Renovation & Remodeling","topic":"flooring","parent":"bathroom-remodel-cost-calculator","description":"Build a small bathroom remodel budget by separating fixtures, surfaces, plumbing and labor.","answer":"A small bathroom can still have a complex budget because labor and plumbing do not shrink in direct proportion to room area. List demolition, waterproofing, tile, vanity, toilet, shower or tub, fixtures, electrical, ventilation, disposal and labor separately.","steps":[("Lock the scope","Decide whether the layout and plumbing locations stay."),("Measure surfaces","Calculate floor, shower wall and backsplash tile separately."),("List fixtures","Record vanity, toilet, tub or shower, faucets and accessories."),("Add trade work","Include demolition, plumbing, electrical, waterproofing and installation.")],"formula":"budget = materials + demolition + trade labor + permits + disposal + contingency","example":"A 40 ft² bathroom can cost more than a larger cosmetic room if it requires a plumbing relocation or full waterproof shower rebuild.","mistakes":"Using room area alone, forgetting waterproofing, and treating fixtures as the entire project cost.","faqs":[("Does a small bathroom always cost less?","Usually material quantity is lower, but labor and plumbing complexity can dominate."),("Should tile labor be separate?","Yes, especially for shower walls, niches and complex patterns."),("Are permits included?","Permit requirements and fees depend on location and scope.") ]},
        {"slug":"kitchen-backsplash-tile-calculator","title":"How to Calculate Kitchen Backsplash Tile","category":"Flooring & Tile","topic":"flooring","parent":"kitchen-tile-calculator","description":"Measure backsplash runs, subtract major openings and calculate tile boxes with waste.","answer":"Measure every backsplash run as width × height. Convert inches to feet, add the runs, subtract only large untiled areas, then add an allowance for cuts, outlets, corners and pattern matching.","steps":[("Map the runs","Record sink wall, range wall and short returns separately."),("Convert dimensions","18 inches equals 1.5 feet."),("Calculate net area","Multiply each run width by height and add them."),("Round the order","Apply waste, then divide by actual box coverage and round up.")],"formula":"boxes = ceil((net backsplash area × waste factor) ÷ box coverage)","example":"A 16 ft run at 18 in high is 16 × 1.5 = 24 ft² before waste.","mistakes":"Subtracting every outlet opening, forgetting side returns, and using floor-tile box coverage for a different backsplash product.","faqs":[("Should outlets be subtracted?","Usually small outlets are left in because they create cuts and breakage."),("Does a herringbone pattern need more?","Often yes because of additional angled cuts."),("Should the range wall be measured separately?","Yes, especially when the height or material changes.") ]},
        {"slug":"room-flooring-square-footage-guide","title":"How to Calculate Room Flooring Square Footage","category":"Flooring & Tile","topic":"flooring","parent":"room-flooring-calculator","description":"Calculate flooring square footage for rectangular, L-shaped and multi-room layouts.","answer":"For a rectangle multiply length × width. For an L-shaped room divide it into rectangles, calculate each area and add them. Apply waste only after the measured total is complete.","steps":[("Sketch the footprint","Mark closets, alcoves and permanent untiled areas."),("Split irregular shapes","Use rectangles that do not overlap."),("Add measured areas","Keep all dimensions in the same unit."),("Apply waste and boxes","Use layout complexity and exact carton coverage.")],"formula":"total area = area 1 + area 2 + ...; boxes = ceil(area × waste ÷ box coverage)","example":"A 12 × 10 room plus a 3 × 4 alcove is 120 + 12 = 132 ft² before waste.","mistakes":"Double-counting an L-shaped corner, subtracting movable furniture, and rounding each section separately.","faqs":[("Do I include closets?","Include them if they receive the same flooring."),("Do I subtract cabinets?","Subtract only fixed areas that definitely will not be covered."),("When is waste added?","After total measured area, before package rounding.") ]},
        {"slug":"garden-bed-soil-depth-guide","title":"Garden Bed Soil Depth Planning Guide","category":"Landscaping","topic":"landscaping","parent":"garden-bed-soil-calculator","description":"Choose a target soil depth and calculate garden-bed soil in cubic feet, yards or bags.","answer":"Soil depth depends on what is being grown, existing soil and the bed construction. Measure the inside bed area, choose a planting-appropriate depth, multiply area by depth in feet and convert the result to yards or bags.","steps":[("Measure inside dimensions","Do not use the outside frame if the walls have thickness."),("Check existing soil","The bed may not need to be filled from zero."),("Set target depth","Use crop or horticultural guidance."),("Convert quantity","Divide cubic feet by 27 or by bag volume.")],"formula":"soil volume(ft³) = length × width × depth(ft); yd³ = ft³ ÷ 27","example":"A 4 × 8 ft bed filled 12 in deep needs 32 ft³, about 1.19 yd³.","mistakes":"Ignoring existing soil, using outside dimensions, and assuming a bag's volume from its weight.","faqs":[("Should soil depth be the same for every crop?","No. Rooting needs differ."),("How many bags per yard?","27 ÷ cubic feet per bag."),("Does soil settle?","Bulk material can settle; ask the supplier how delivered volume is represented.") ]},
        {"slug":"river-rock-coverage-guide","title":"How to Calculate River Rock Coverage","category":"Landscaping","topic":"landscaping","parent":"river-rock-calculator","description":"Estimate river rock volume and weight from landscape area, installed depth and bulk density.","answer":"Calculate area × installed depth for volume. Convert cubic feet to yards and multiply by the selected material density only when a weight estimate is needed. Rock size and density vary, so use supplier data.","steps":[("Measure the bed","Split curved or irregular beds into simple sections."),("Choose depth","Use a depth suitable for the intended decorative or drainage use."),("Calculate volume","Convert inches to feet before multiplying."),("Check weight","Use the supplier's bulk density, not a generic rock weight.")],"formula":"cubic yards = area × depth(ft) ÷ 27; weight = volume × bulk density","example":"A 150 ft² bed at 2 in deep is 25 ft³, or about 0.93 yd³.","mistakes":"Using the same density for every stone, forgetting landscape fabric or edging needs, and confusing coverage depth with rock diameter.","faqs":[("Does larger rock cover differently?","Yes. Voids and placement affect actual coverage."),("Can river rock be used for drainage?","Use project-specific drainage design; decorative coverage calculations are not drainage engineering."),("Should I order extra?","Supplier and site conditions determine the allowance.") ]},
        {"slug":"roof-shingle-waste-guide","title":"Roof Shingle Waste and Bundle Planning Guide","category":"Roofing, Decks & Fences","topic":"roofing-decks-fences","parent":"shingle-calculator","description":"Convert roof surface area into squares and bundles while accounting for valleys, hips, cuts and product coverage.","answer":"Calculate roof surface area, divide by 100 for squares, then use the exact bundle coverage for the chosen shingle. Waste depends on roof shape and must not be confused with pitch surface area.","steps":[("Measure roof planes","Use safe measurements and separate pitches."),("Calculate squares","Surface area ÷ 100."),("Review geometry","Valleys, hips, dormers and penetrations increase cuts."),("Round bundles","Use the package label and include starter and ridge products separately.")],"formula":"squares = roof area(ft²) ÷ 100; bundles = ceil(purchase area ÷ bundle coverage)","example":"A 2,100 ft² roof equals 21 raw squares before waste and accessory calculations.","mistakes":"Assuming three bundles always equal one square, ignoring starter and ridge material, and measuring an unsafe roof without proper methods.","faqs":[("Are valleys included?","They are part of roof geometry but may require separate installation materials."),("Does pitch create waste?","Pitch changes surface area; cuts and layout create waste."),("Is this safe roof measurement advice?","No. Do not access a roof unsafely.") ]},
        {"slug":"deck-material-waste-guide","title":"Deck Material Waste Planning Guide","category":"Roofing, Decks & Fences","topic":"roofing-decks-fences","parent":"deck-board-calculator","description":"Plan deck-board waste from board length, layout direction, stairs, picture framing and offcuts.","answer":"Calculate rows and total linear feet, then review board lengths and layout. Waste depends on the deck shape, board direction, stair cuts, picture framing and whether usable offcuts can be reused.","steps":[("Measure deck zones","Separate main field, stairs, landings and borders."),("Choose board direction","Direction changes board lengths and offcuts."),("Calculate rows","Use actual face width plus required gap."),("Review board lengths","Round to purchasable lengths and keep a visible waste allowance.")],"formula":"rows ≈ deck width ÷ (board face width + gap); linear feet = rows × board run","example":"A 144 in deck width with a 5.625 in board module needs about 26 rows before border and waste adjustments.","mistakes":"Using nominal board width, ignoring picture-frame borders, and assuming every offcut can be reused.","faqs":[("Do composite boards need different gaps?","Follow the selected manufacturer's spacing instructions."),("Are stairs separate?","Yes, stairs can change board count and create additional cuts."),("Does this size joists?","No. Framing is a separate structural design.") ]},
        {"slug":"exterior-paint-coverage-guide","title":"Exterior Paint Coverage Planning Guide","category":"Paint & Finishes","topic":"paint","parent":"exterior-paint-calculator","description":"Estimate exterior paint from wall elevations, openings, surface texture, coats and product coverage.","answer":"Measure each wall elevation, calculate gross area, subtract meaningful openings and divide coat-area by the exact product coverage. Rough siding and masonry usually need more careful allowance than smooth surfaces.","steps":[("Measure elevations","Record length and height for each wall plane."),("Subtract major openings","Remove large doors and windows."),("Assess surface","Texture, porosity and previous color affect coverage."),("Calculate coats","Use primer and finish product coverage separately.")],"formula":"gallons = (paintable area × coats) ÷ product coverage per gallon","example":"A 1,200 ft² exterior with 2 coats and a 350 ft²/gal product has 6.86 theoretical gallons before rounding and surface allowance.","mistakes":"Using floor area, assuming smooth-wall coverage on rough siding, and forgetting trim, soffits or separate colors.","faqs":[("Should trim be separate?","Yes, trim usually uses a different product and coverage rate."),("Does masonry need more paint?","Porous masonry can absorb more coating; follow the product system."),("Should primer be included?","Include primer as a separate coat and product.") ]}
    ]
